CREATE TABLE workspaces (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100), slug TEXT NOT NULL UNIQUE CHECK(length(slug) BETWEEN 1 AND 80), icon_url TEXT, created_by TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE workspace_members (workspace_id TEXT NOT NULL REFERENCES workspaces(id), user_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','admin','member')), joined_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,user_id));
CREATE UNIQUE INDEX one_owner ON workspace_members(workspace_id) WHERE role = 'owner';
CREATE INDEX member_workspaces ON workspace_members(user_id,workspace_id);

CREATE TABLE messages (id TEXT PRIMARY KEY NOT NULL, channel_id TEXT NOT NULL, workspace_id TEXT NOT NULL, user_id TEXT NOT NULL, body TEXT NOT NULL CHECK(length(body) <= 10000), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0 CHECK(is_deleted IN (0,1)), FOREIGN KEY(workspace_id,channel_id) REFERENCES channels(workspace_id,id), UNIQUE(workspace_id,id));
CREATE INDEX message_timeline ON messages(workspace_id,channel_id,created_at DESC,id DESC);
CREATE TABLE reactions (message_id TEXT NOT NULL, user_id TEXT NOT NULL, emoji TEXT NOT NULL CHECK(length(emoji) BETWEEN 1 AND 32), workspace_id TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(message_id,user_id,emoji), FOREIGN KEY(workspace_id,message_id) REFERENCES messages(workspace_id,id));

ALTER TABLE channels ADD COLUMN is_archived INTEGER NOT NULL DEFAULT 0 CHECK(is_archived IN (0,1));
ALTER TABLE messages ADD COLUMN edited_at INTEGER;
ALTER TABLE messages ADD COLUMN deleted_at INTEGER;
UPDATE messages SET edited_at = updated_at WHERE updated_at != created_at AND is_deleted = 0;
UPDATE messages SET deleted_at = updated_at WHERE is_deleted = 1;
CREATE UNIQUE INDEX message_channel_scope ON messages(workspace_id,channel_id,id);
CREATE TABLE message_reactions (message_id TEXT NOT NULL, channel_id TEXT NOT NULL, workspace_id TEXT NOT NULL, user_id TEXT NOT NULL, emoji TEXT NOT NULL CHECK(length(emoji) BETWEEN 1 AND 32), created_at INTEGER NOT NULL, PRIMARY KEY(message_id,user_id,emoji), FOREIGN KEY(workspace_id,channel_id,message_id) REFERENCES messages(workspace_id,channel_id,id));
INSERT INTO message_reactions(message_id,channel_id,workspace_id,user_id,emoji,created_at) SELECT r.message_id,m.channel_id,r.workspace_id,r.user_id,r.emoji,r.created_at FROM reactions r JOIN messages m ON m.id = r.message_id AND m.workspace_id = r.workspace_id;
CREATE TABLE activity_log (id TEXT PRIMARY KEY NOT NULL, workspace_id TEXT NOT NULL REFERENCES workspaces(id), actor_id TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, changes TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL);
CREATE INDEX activity_workspace ON activity_log(workspace_id,created_at DESC);
CREATE INDEX activity_entity ON activity_log(workspace_id,entity_type,entity_id,created_at DESC);
INSERT INTO activity_log(id,workspace_id,actor_id,entity_type,entity_id,action,changes,created_at) SELECT id,workspace_id,actor_id,CASE WHEN action LIKE 'workspace_member_%' THEN 'member' WHEN action LIKE 'workspace_%' THEN 'workspace' WHEN action LIKE 'channel_%' THEN 'channel' ELSE 'message' END,target_id,action,'{}',created_at FROM audit_log;

ALTER TABLE channels ADD COLUMN topic TEXT NOT NULL DEFAULT '' CHECK(length(topic) <= 250);
ALTER TABLE channels ADD COLUMN archived_at INTEGER;
UPDATE channels SET archived_at = created_at WHERE is_archived = 1;
ALTER TABLE workspace_members ADD COLUMN display_name TEXT NOT NULL DEFAULT '' CHECK(length(display_name) <= 80);
ALTER TABLE workspace_members ADD COLUMN avatar_url TEXT;
INSERT OR IGNORE INTO audit_log(id,workspace_id,actor_id,action,target_id,created_at) SELECT id,workspace_id,actor_id,action,entity_id,created_at FROM activity_log;
CREATE TRIGGER audit_activity AFTER INSERT ON audit_log BEGIN INSERT INTO activity_log(id,workspace_id,actor_id,entity_type,entity_id,action,changes,created_at) VALUES (NEW.id,NEW.workspace_id,NEW.actor_id,CASE WHEN NEW.action LIKE '%member%' OR NEW.action LIKE '%profile%' THEN 'member' WHEN NEW.action LIKE '%channel%' THEN 'channel' WHEN NEW.action LIKE 'workspace%' THEN 'workspace' ELSE 'message' END,NEW.target_id,NEW.action,'{}',NEW.created_at); END;

ALTER TABLE messages ADD COLUMN parent_id TEXT REFERENCES messages(id);
CREATE INDEX thread_replies ON messages(workspace_id,channel_id,parent_id,created_at DESC,id DESC);
CREATE TRIGGER thread_scope BEFORE INSERT ON messages WHEN NEW.parent_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM messages root WHERE root.id = NEW.parent_id AND root.workspace_id = NEW.workspace_id AND root.channel_id = NEW.channel_id AND root.parent_id IS NULL AND root.deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'invalid_thread_root'); END;
CREATE TRIGGER thread_parent_immutable BEFORE UPDATE OF parent_id ON messages WHEN OLD.parent_id IS NOT NEW.parent_id BEGIN SELECT RAISE(ABORT,'immutable_thread_root'); END;
ALTER TABLE workspace_members ADD COLUMN mention_handle TEXT;
UPDATE workspace_members SET mention_handle = 'uid-' || lower(hex(CAST(user_id AS BLOB)));
CREATE UNIQUE INDEX member_mention_handle ON workspace_members(workspace_id,mention_handle);
CREATE TRIGGER member_handle AFTER INSERT ON workspace_members BEGIN UPDATE workspace_members SET mention_handle = 'uid-' || lower(hex(CAST(NEW.user_id AS BLOB))) WHERE workspace_id = NEW.workspace_id AND user_id = NEW.user_id; END;
CREATE UNIQUE INDEX channel_member_scope ON channel_members(workspace_id,channel_id,user_id);
CREATE TABLE mentions (message_id TEXT NOT NULL,workspace_id TEXT NOT NULL,channel_id TEXT NOT NULL,user_id TEXT NOT NULL,created_at INTEGER NOT NULL,seen_at INTEGER,PRIMARY KEY(message_id,user_id),FOREIGN KEY(workspace_id,channel_id,message_id) REFERENCES messages(workspace_id,channel_id,id),FOREIGN KEY(workspace_id,channel_id,user_id) REFERENCES channel_members(workspace_id,channel_id,user_id) ON DELETE CASCADE);
CREATE INDEX mentions_inbox ON mentions(workspace_id,user_id,created_at DESC,message_id DESC);
CREATE TRIGGER mentions_on_send AFTER INSERT ON messages BEGIN INSERT OR IGNORE INTO mentions(message_id,workspace_id,channel_id,user_id,created_at) SELECT NEW.id,NEW.workspace_id,NEW.channel_id,matched.user_id,NEW.updated_at FROM (SELECT DISTINCT target.user_id FROM workspace_members target JOIN channel_members eligible ON eligible.workspace_id = target.workspace_id AND eligible.user_id = target.user_id AND eligible.channel_id = NEW.channel_id JOIN (WITH RECURSIVE positions(pos) AS (SELECT instr(NEW.body,'@') WHERE instr(NEW.body,'@') > 0 UNION ALL SELECT pos + instr(substr(NEW.body,pos+1),'@') FROM positions WHERE instr(substr(NEW.body,pos+1),'@') > 0) SELECT pos FROM positions) tokens WHERE target.workspace_id = NEW.workspace_id AND target.user_id != NEW.user_id AND NEW.deleted_at IS NULL AND substr(lower(NEW.body),tokens.pos+1,length(target.mention_handle)) = target.mention_handle AND (tokens.pos = 1 OR substr(NEW.body,tokens.pos-1,1) NOT GLOB '[a-zA-Z0-9_@.-]') AND substr(NEW.body,tokens.pos+length(target.mention_handle)+1,1) NOT GLOB '[a-zA-Z0-9_-]') matched; END;
CREATE TRIGGER mentions_on_edit AFTER UPDATE OF body,deleted_at ON messages BEGIN DELETE FROM mentions WHERE message_id = NEW.id AND user_id NOT IN (SELECT DISTINCT target.user_id FROM workspace_members target JOIN channel_members eligible ON eligible.workspace_id = target.workspace_id AND eligible.user_id = target.user_id AND eligible.channel_id = NEW.channel_id JOIN (WITH RECURSIVE positions(pos) AS (SELECT instr(NEW.body,'@') WHERE instr(NEW.body,'@') > 0 UNION ALL SELECT pos + instr(substr(NEW.body,pos+1),'@') FROM positions WHERE instr(substr(NEW.body,pos+1),'@') > 0) SELECT pos FROM positions) tokens WHERE target.workspace_id = NEW.workspace_id AND target.user_id != NEW.user_id AND NEW.deleted_at IS NULL AND substr(lower(NEW.body),tokens.pos+1,length(target.mention_handle)) = target.mention_handle AND (tokens.pos = 1 OR substr(NEW.body,tokens.pos-1,1) NOT GLOB '[a-zA-Z0-9_@.-]') AND substr(NEW.body,tokens.pos+length(target.mention_handle)+1,1) NOT GLOB '[a-zA-Z0-9_-]'); INSERT OR IGNORE INTO mentions(message_id,workspace_id,channel_id,user_id,created_at) SELECT NEW.id,NEW.workspace_id,NEW.channel_id,matched.user_id,NEW.updated_at FROM (SELECT DISTINCT target.user_id FROM workspace_members target JOIN channel_members eligible ON eligible.workspace_id = target.workspace_id AND eligible.user_id = target.user_id AND eligible.channel_id = NEW.channel_id JOIN (WITH RECURSIVE positions(pos) AS (SELECT instr(NEW.body,'@') WHERE instr(NEW.body,'@') > 0 UNION ALL SELECT pos + instr(substr(NEW.body,pos+1),'@') FROM positions WHERE instr(substr(NEW.body,pos+1),'@') > 0) SELECT pos FROM positions) tokens WHERE target.workspace_id = NEW.workspace_id AND target.user_id != NEW.user_id AND NEW.deleted_at IS NULL AND substr(lower(NEW.body),tokens.pos+1,length(target.mention_handle)) = target.mention_handle AND (tokens.pos = 1 OR substr(NEW.body,tokens.pos-1,1) NOT GLOB '[a-zA-Z0-9_@.-]') AND substr(NEW.body,tokens.pos+length(target.mention_handle)+1,1) NOT GLOB '[a-zA-Z0-9_-]') matched; END;
